CREATE TABLE IF NOT EXISTS restock_watches (id BIGINT AUTO_INCREMENT PRIMARY KEY,owner_id BIGINT NOT NULL,product_id BIGINT NOT NULL,state VARCHAR(255),created_at DATETIME(6),available_at DATETIME(6),seen BOOLEAN NOT NULL,revision BIGINT NOT NULL DEFAULT 0,UNIQUE KEY uq_restock_owner_product(owner_id,product_id),KEY ix_restock_state(state),FOREIGN KEY (owner_id) REFERENCES users(user_id));
